WITH valid_transactions AS (SELECT * FROM transactions WHERE account_id IN (3, 34) OR merchant IN ('7-Eleven', 'Amazon')), agg AS (SELECT CASE WHEN YEAR(txn_time) < 2024 THEN 'before_2024' WHEN YEAR(txn_time) = 2024 THEN '2024' ELSE 'after_2024' END txn_cohort, txn_type, SORT_ARRAY(COLLECT_SET(txn_type)) txn_type_list, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(merchant))) merchant_values FROM valid_transactions GROUP BY CASE WHEN YEAR(txn_time) < 2024 THEN 'before_2024' WHEN YEAR(txn_time) = 2024 THEN '2024' ELSE 'after_2024' END, txn_type) SELECT * FROM agg ORDER BY merchant_values ASC, txn_type ASC, txn_cohort ASC LIMIT 5;
